<?php declare(strict_types=1);
namespace Modules\PromptEngine\Providers;
use Illuminate\Support\ServiceProvider; use Modules\PromptEngine\Interfaces\{CharacterAnalyzerInterface,DesignPlannerInterface,PromptGeneratorInterface,PromptRepositoryInterface}; use Modules\PromptEngine\Repositories\PromptRepository; use Modules\PromptEngine\Services\{CharacterAnalyzerService,DesignPlannerService,PromptAssemblerService}; use Modules\PromptEngine\Services\ImageProviders\{ChatGptImagePromptProvider,FluxPromptProvider,GeminiPromptProvider,GenericPromptProvider,MidjourneyPromptProvider,StableDiffusionPromptProvider};
final class PromptEngineServiceProvider extends ServiceProvider { public function register():void{$this->app->bind(CharacterAnalyzerInterface::class,CharacterAnalyzerService::class);$this->app->bind(DesignPlannerInterface::class,DesignPlannerService::class);$this->app->bind(PromptRepositoryInterface::class,PromptRepository::class);$this->app->singleton(PromptGeneratorInterface::class,fn()=>new PromptAssemblerService([new GeminiPromptProvider,new ChatGptImagePromptProvider,new MidjourneyPromptProvider,new FluxPromptProvider,new StableDiffusionPromptProvider,new GenericPromptProvider]));} public function boot():void{$this->publishes([base_path('Modules/PromptEngine/config/config.php')=>config_path('prompt-engine.php')],'prompt-engine-config');$this->publishes([base_path('Modules/PromptEngine/Templates')=>resource_path('prompt-engine')],'prompt-engine-templates');} }
